+	writer, err := f.NewWriter(parsing.DefaultWriterOptions())
+	if err != nil {
+		t.Fatalf("failed to create writer: %v", err)
+	}
+	out, err := writer.Write(val)
+	if err != nil {
+		t.Fatalf("failed to write: %v", err)
+	}
